#nullable enable // autogenerated

using System.Collections.Generic;
using MVZ2.Managers;
using MVZ2.Options;
using MVZ2Logic;
using UnityEngine;

namespace MVZ2.Level
{
    public partial class LevelController
    {
        public void AddSlowMotion(SlowMotion slowMotion)
        {
            slowMotions.Add(slowMotion);
        }
        public float GetSlowMotionMultiplier()
        {
            float multiplier = 1;
            foreach (var slowMotion in slowMotions)
            {
                multiplier *= slowMotion.multiplier;
            }
            return multiplier;
        }
        private void UpdateFrame_SlowMotion(float deltaTime)
        {
            foreach (var slowMotion in slowMotions)
            {
                slowMotion.timeout -= deltaTime;
            }
            slowMotions.RemoveAll(s => s.timeout <= 0);
        }
        private List<SlowMotion> slowMotions = new List<SlowMotion>();
    }
}
